"""Cache decoded samples once and gather single-problem batches on the GPU."""

import torch

from code.unified_selector.data import UnifiedProblemDataset, collate_single_problem


_CACHE = {}


class TensorBatchLoader:
    def __init__(self, batch, batch_size, shuffle, drop_last):
        self.batch = batch
        self.batch_size = batch_size
        self.shuffle = shuffle
        self.drop_last = drop_last
        self.lengths = batch["n"].cpu()
        self.size = len(self.lengths)

    def __len__(self):
        return self.size // self.batch_size if self.drop_last else (self.size + self.batch_size - 1) // self.batch_size

    def __iter__(self):
        order = torch.randperm(self.size) if self.shuffle else torch.arange(self.size)
        stop = self.size - self.size % self.batch_size if self.drop_last else self.size
        for start in range(0, stop, self.batch_size):
            idx = order[start : min(start + self.batch_size, stop)]
            max_n = int(self.lengths[idx].max())
            device_idx = idx.to(self.batch["costs"].device)
            batch = {}
            for key, value in self.batch.items():
                if not torch.is_tensor(value) or key == "pool_ids":
                    batch[key] = value
                    continue
                if key in ("node", "node_mask", "node_geom"):
                    value = value[:, :max_n]
                elif key == "matrix":
                    value = value[:, :max_n, :max_n]
                batch[key] = value.index_select(0, device_idx)
            yield batch


def make_tensor_loader(problem, split, batch_size, shuffle, device, coord_augment=0):
    key = (problem, split, str(device), coord_augment)
    if key not in _CACHE:
        dataset = UnifiedProblemDataset(problem, split, coord_augment=coord_augment)
        batch = collate_single_problem([dataset[i] for i in range(len(dataset))])
        batch = {k: v.to(device) if torch.is_tensor(v) else v for k, v in batch.items()}
        _CACHE[key] = batch
        size_mb = sum(v.numel() * v.element_size() for v in batch.values() if torch.is_tensor(v)) / 2**20
        print(f"[cache] {problem}/{split}: {len(dataset)} instances, {size_mb:.1f} MiB on {device}", flush=True)
    return TensorBatchLoader(_CACHE[key], batch_size, shuffle, drop_last=(split == "train"))
def collate_problem_batch(dataset: str, dataset_obj, indices: Sequence[int]) -> Tuple[Tuple[torch.Tensor, ...], int]:
    problem = dataset_problem(dataset)
    samples = [dataset_obj[i] for i in indices]
    scale = infer_scale_from_sample(dataset, samples[0])

    if problem == "CVRP":
        depot = []
        loc = []
        demand = []
        for sample in samples:
            depot.append(normalize_tensor_like(sample["depot"]).squeeze(0))
            loc.append(normalize_tensor_like(sample["loc"]).squeeze(0))
            demand.append(normalize_tensor_like(sample["demand"]).squeeze(0))
        return (
            torch.stack(depot, dim=0),
            torch.stack(loc, dim=0),
            torch.stack(demand, dim=0),
        ), scale

    depot_xy = []
    node_xy = []
    node_demand = []
    route_limit = []
    service_time = []
    tw_start = []
    tw_end = []

    for sample in samples:
        depot_xy.append(normalize_tensor_like(sample["depot_xy"]))
        node_xy.append(normalize_tensor_like(sample["node_xy"]))
        node_demand.append(normalize_tensor_like(sample["node_demand"]))
        if "route_limit" in sample:
            route_limit.append(float(sample["route_limit"]))
        if "service_time" in sample:
            service_time.append(normalize_tensor_like(sample["service_time"]))
            tw_start.append(normalize_tensor_like(sample["tw_start"]))
            tw_end.append(normalize_tensor_like(sample["tw_end"]))

    depot_xy_t = torch.stack(depot_xy, dim=0)
    node_xy_t = torch.stack(node_xy, dim=0)
    node_demand_t = torch.stack(node_demand, dim=0)

    if service_time and route_limit:
        return (
            depot_xy_t,
            node_xy_t,
            node_demand_t,
            torch.tensor(route_limit, dtype=torch.float32),
            torch.stack(service_time, dim=0),
            torch.stack(tw_start, dim=0),
            torch.stack(tw_end, dim=0),
        ), scale
    if service_time:
        return (
            depot_xy_t,
            node_xy_t,
            node_demand_t,
            torch.stack(service_time, dim=0),
            torch.stack(tw_start, dim=0),
            torch.stack(tw_end, dim=0),
        ), scale
    if route_limit:
        return (
            depot_xy_t,
            node_xy_t,
            node_demand_t,
            torch.tensor(route_limit, dtype=torch.float32),
        ), scale
    return (
        depot_xy_t,
        node_xy_t,
        node_demand_t,
    ), scale
"""Resume state and plots for controlled training experiments."""

import random

import numpy as np
import torch


def capture_rng():
    return dict(python=random.getstate(), numpy=np.random.get_state(),
                torch=torch.get_rng_state(), cuda=torch.cuda.get_rng_state_all() if torch.cuda.is_available() else [])


def restore_rng(state):
    random.setstate(state["python"])
    np.random.set_state(state["numpy"])
    torch.set_rng_state(state["torch"].cpu())
    if state["cuda"]:
        torch.cuda.set_rng_state_all([s.cpu() for s in state["cuda"]])


def plot_history(history, directory):
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt

    fig, axes = plt.subplots(2, 3, figsize=(15, 8))
    for key in ("loss", "ce", "pair", "risk"):
        points = [r for r in history if key in r["train"]]
        if points:
            axes[0, 0].plot([r["epoch"] + 1 for r in points], [r["train"][key] for r in points], label=key)
    axes[0, 0].set_title("Training objective components"); axes[0, 0].legend()
    for source in ("train_eval", "val"):
        rows = [r for r in history if source in r]
        for ax, metric in ((axes[0, 1], "macro_ce"), (axes[0, 2], "macro_top1"), (axes[1, 0], "macro_vs_sbs_pct")):
            ax.plot([r["epoch"] + 1 for r in rows], [r[source][metric] for r in rows], label=source)
            ax.set_title(metric); ax.legend()
    axes[1, 1].plot([r["epoch"] + 1 for r in history], [r["lr"] for r in history]); axes[1, 1].set_title("Learning rate")
    axes[1, 2].plot([r["epoch"] + 1 for r in history], [r["train"]["grad_norm"] for r in history]); axes[1, 2].set_title("Unclipped gradient norm")
    for ax in axes.flat:
        ax.set_xlabel("Epoch (1-based)"); ax.grid(alpha=.25)
    fig.tight_layout(); fig.savefig(directory / "training_curves.png", dpi=150); plt.close(fig)

